CREATE TABLE IF NOT EXISTS regional_music_rank_history (
  service TEXT NOT NULL,
  chart_id TEXT NOT NULL,
  published_at TEXT NOT NULL,
  issue INTEGER NOT NULL,
  volid INTEGER NOT NULL,
  canonical_artist TEXT NOT NULL,
  rank INTEGER NOT NULL,
  previous_rank INTEGER,
  rank_count INTEGER,
  author_name TEXT,
  title TEXT NOT NULL,
  album_name TEXT,
  album_audio_id INTEGER,
  audio_id INTEGER NOT NULL,
  PRIMARY KEY (service, chart_id, issue, canonical_artist, audio_id)
);

